import jax
import jax.numpy as jnp
import flax.linen as nn
import optax
from typing import Dict, Any, Sequence

# --- Hyperparameters ---
def _define_hyperparameters():
    return {
        'peak_learning_rate': 0.001, 'total_train_steps': 200000, 'warmup_steps': 2000,
        'd_model': 256, 'dropout_rate': 0.1, 'ds_kernel_size': 7,
        'dilations': [1, 2, 4, 8, 16], 'motif_kernel_size': 5,
        'head_intermediate_dim': 128, 'sgrna_len': 20,
        'pos_embedding_dim': 16, 'context_window_size': 3, 'max_overall_seq_len': 1200,
        'gate_intermediate_dim': 64, 'reg_head_dropout': 0.05
    }

# --- Optimizer ---
def create_optimizer(learning_rate: float = 0.001):
    hparams = _define_hyperparameters()
    lr_schedule = optax.warmup_cosine_decay_schedule(init_value=0.0, peak_value=hparams.get('peak_learning_rate', learning_rate),
                                                     warmup_steps=hparams.get('warmup_steps'), decay_steps=hparams.get('total_train_steps'))
    return optax.chain(optax.clip_by_global_norm(0.75),
                       optax.adamw(learning_rate=lr_schedule, weight_decay=0.02))

# --- CPE Components ---
class ContextEncoder(nn.Module):
    output_dim: int
    @nn.compact
    def __call__(self, local_context_window):
        flat_context = local_context_window.reshape(local_context_window.shape[0], -1)
        return nn.gelu(nn.Dense(self.output_dim, name='context_dense')(flat_context))

class CPE_Generator(nn.Module):
    hparams: Dict[str, Any]
    @nn.compact
    def __call__(self, x_raw):
        batch_size, seq_len, d_input = x_raw.shape
        pos_table = self.param('pos_embeddings_table', nn.initializers.normal(stddev=0.01),
                               (self.hparams['max_overall_seq_len'], self.hparams['pos_embedding_dim']))
        pad_width = self.hparams['context_window_size'] // 2
        padded_x = jnp.pad(x_raw, ((0,0), (pad_width, pad_width), (0,0)), mode='constant')
        windows = jnp.stack([padded_x[:, i : i + self.hparams['context_window_size'], :].reshape(batch_size, -1) for i in range(seq_len)], axis=1)
        encoder = ContextEncoder(output_dim=self.hparams['pos_embedding_dim'], name='context_encoder')
        encoded_contexts = encoder(windows.reshape(-1, self.hparams['context_window_size'] * d_input)).reshape(batch_size, seq_len, -1)
        pos_sliced = pos_table[:seq_len] 
        return jnp.tile(pos_sliced[None, :, :], (batch_size, 1, 1)) * encoded_contexts

# --- Backbone Components ---
class DeepCPE_DSConvBlock(nn.Module):
    hparams: Dict[str, Any]; cpe_raw_signals: Any; dilation: int
    @nn.compact
    def __call__(self, x, deterministic=True):
        residual = x
        h = nn.LayerNorm()(x)
        h_conv = nn.Conv(features=self.hparams['d_model'], kernel_size=(self.hparams['ds_kernel_size'],),
                         feature_group_count=self.hparams['d_model'], padding='SAME',
                         kernel_dilation=(self.dilation,))(h)
        h_conv = nn.gelu(h_conv)
        h_conv_output = nn.Conv(features=self.hparams['d_model'], kernel_size=(1,))(h_conv)
        cpe_projected = nn.gelu(nn.Dense(self.hparams['d_model'])(self.cpe_raw_signals))
        combined = jnp.concatenate([h_conv_output, cpe_projected], axis=-1)
        gate_input = nn.gelu(nn.Dense(self.hparams['gate_intermediate_dim'])(combined))
        gate_factor = nn.sigmoid(nn.Dense(self.hparams['d_model'])(gate_input))
        modulated_h = h_conv_output * gate_factor
        return residual + nn.Dropout(rate=self.hparams['dropout_rate'])(modulated_h, deterministic=deterministic)

# --- Pooling ---
class AdaptivePooling(nn.Module):
    hparams: Dict[str, Any]
    @nn.compact
    def __call__(self, F):
        mean_p, max_p = jnp.mean(F, axis=1), jnp.max(F, axis=1)
        gate = nn.sigmoid(nn.Dense(self.hparams['d_model'])(jnp.concatenate([mean_p, max_p], axis=-1)))
        return gate * mean_p + (1 - gate) * max_p

# --- Heads ---
class GenericHead(nn.Module): ...
class RegressionHead(nn.Module): ...

# --- Full Model ---
class GrandSynthesisModel(nn.Module):
    hparams: Dict[str, Any]
    @nn.compact
    def __call__(self, x, deterministic=True):
        task_type, d_output = self.hparams['task_type'], self.hparams['d_output']
        cpe_signals = CPE_Generator(hparams=self.hparams)(x)

        if self.hparams.get('dataset') == 'CRI-Off':
            sgrna, target = x[:, :self.hparams['sgrna_len'], :], x[:, self.hparams['sgrna_len']:, :]
            cpe_sgrna, cpe_target = cpe_signals[:, :self.hparams['sgrna_len'], :], cpe_signals[:, self.hparams['sgrna_len']:, :]

            sgrna_features = self.run_backbone(sgrna, cpe_sgrna, deterministic, name_prefix="sgrna_")
            target_features = self.run_backbone(target, cpe_target, deterministic, name_prefix="target_")

            sgrna_p = AdaptivePooling(hparams=self.hparams)(sgrna_features)
            target_p = AdaptivePooling(hparams=self.hparams)(target_features)
            sgrna_cal = sgrna_p / (jnp.linalg.norm(sgrna_p, axis=-1, keepdims=True) + 1e-6)
            target_cal = target_p / (jnp.linalg.norm(target_p, axis=-1, keepdims=True) + 1e-6)
            interaction = jnp.concatenate([sgrna_cal, target_cal, jnp.abs(sgrna_cal - target_cal), sgrna_cal * target_cal], axis=-1)
            return self.RegressionHead(hparams=self.hparams, d_output=1)(interaction, deterministic).squeeze(-1)
        else:
            cnn_features = self.run_backbone(x, cpe_signals, deterministic)
            main_pooled = AdaptivePooling(hparams=self.hparams)(cnn_features)
            motif_pooled = jnp.max(nn.gelu(nn.Conv(self.hparams['d_model'], (self.hparams['motif_kernel_size'],))(cnn_features)), axis=1)
            fused = nn.LayerNorm()(jnp.concatenate([main_pooled, motif_pooled], axis=-1))
            if "regression" in task_type: output = self.RegressionHead(hparams=self.hparams, d_output=d_output)(fused, deterministic)
            else: output = self.GenericHead(hparams=self.hparams, d_output=d_output)(fused, deterministic)
            return output.squeeze(-1) if task_type == 'regression' else output

    def run_backbone(self, seq, cpe, deterministic, name_prefix=""):
        h = nn.gelu(nn.Dense(self.hparams['d_model'], name=f"{name_prefix}initial_dense")(seq))
        for i, d in enumerate(self.hparams['dilations']):
            h = DeepCPE_DSConvBlock(hparams=self.hparams, cpe_raw_signals=cpe, dilation=d, name=f"{name_prefix}dsconv_block_{i}")(h, deterministic)
        return h

    class GenericHead(nn.Module):
        hparams: Dict[str, Any]; d_output: int
        @nn.compact
        def __call__(self, z, deterministic=True):
            z = nn.gelu(nn.Dense(self.hparams['head_intermediate_dim'])(z))
            z = nn.Dropout(rate=self.hparams['dropout_rate'])(z, deterministic=deterministic)
            return nn.Dense(self.d_output)(z)

    class RegressionHead(nn.Module):
        hparams: Dict[str, Any]; d_output: int
        @nn.compact
        def __call__(self, z, deterministic=True):
            norm = jnp.linalg.norm(z, axis=-1, keepdims=True)
            z = z / (norm + 1e-6)
            z = nn.gelu(nn.Dense(self.hparams['head_intermediate_dim'])(z))
            z = nn.Dropout(rate=self.hparams['reg_head_dropout'])(z, deterministic=deterministic)
            return nn.Dense(self.d_output)(z)

class NetworkWrapper:
    def __init__(self, m): self.module = m
    def init(self, r, d): return self.module.init({'params': r, 'dropout': jax.random.PRNGKey(0)}, d, deterministic=True)['params']
    def apply(self, p, x, deterministic=True, rng_key=None):
        return self.module.apply({'params': p}, x, deterministic=deterministic, rngs={'dropout': rng_key or jax.random.PRNGKey(0)})

def create_network(hparams):
    hparams.update({'task_type': hparams.get('task_type'), 'd_output': hparams.get('d_output'), 'dataset': hparams.get('dataset')})
    return NetworkWrapper(GrandSynthesisModel(hparams))
